type OrderEvent =
  | { type: 'OrderPlaced'; items: Item[] }
  | { type: 'OrderShipped'; trackingNumber: string }
  | { type: 'OrderCancelled'; reason: string };

type OrderState = { items: Item[]; status: string; tracking?: string };

// Pure apply function — no side effects
function apply(state: OrderState, event: OrderEvent): OrderState {
  switch (event.type) {
    case 'OrderPlaced':   return { ...state, items: event.items, status: 'pending' };
    case 'OrderShipped':  return { ...state, status: 'shipped', tracking: event.trackingNumber };
    case 'OrderCancelled':return { ...state, status: 'cancelled' };
  }
}

// Rehydrate by folding the event log
const currentState = events.reduce(apply, {} as OrderState);

// Async projection handler consuming Kafka events
class OrderSummaryProjection {
  async on(event: OrderPlacedEvent): Promise<void> {
    await this.db.upsert('order_summaries', {
      id: event.orderId,
      customerId: event.customerId,
      status: 'placed',
      total: event.total,
      createdAt: event.occurredAt,
    });
  }

  async on(event: OrderShippedEvent): Promise<void> {
    await this.db.update('order_summaries', event.orderId, {
      status: 'shipped',
      trackingNumber: event.trackingNumber,
    });
  }
}

async function loadAggregate(aggregateId: string): Promise<OrderAggregate> {
  // 1. Find the most recent snapshot
  const snapshot = await eventStore.loadSnapshot(aggregateId);
  const fromVersion = snapshot?.version ?? 0;
  const baseState   = snapshot?.state   ?? OrderAggregate.empty();

  // 2. Load only delta events after the snapshot
  const deltaEvents = await eventStore.loadEvents(aggregateId, { fromVersion });

  // 3. Replay delta onto snapshot state
  return deltaEvents.reduce(apply, baseState);
}

// Rebuild a projection from scratch via full replay
async function rebuildOrderSummaryProjection(): Promise<void> {
  await db.truncate('order_summaries'); // start fresh

  const stream = eventStore.streamAll({ eventTypes: ['OrderPlaced', 'OrderShipped', 'OrderCancelled'] });

  for await (const event of stream) {
    await orderSummaryProjection.handle(event);
  }

  console.log('Projection rebuilt from event log.');
}

