class Order {  // Aggregate root
  private id: string;
  private items: OrderLine[] = [];
  private status: 'pending' | 'confirmed' | 'shipped' = 'pending';

  addItem(item: OrderLine): OrderItemAdded {
    if (this.status !== 'pending') {
      throw new Error('Cannot add items to a confirmed order');
    }
    this.items.push(item);
    return new OrderItemAdded(this.id, item);
  }

  confirm(): OrderConfirmed {
    if (this.items.length === 0) {
      throw new Error('Cannot confirm an empty order');
    }
    this.status = 'confirmed';
    return new OrderConfirmed(this.id);
  }
}

